def transforms(cells, N):
    out = {}
    out['id']   = {(r,c) for r,c in cells}
    out['cw']   = {(c, N-1-r) for r,c in cells}
    out['ccw']  = {(N-1-c, r) for r,c in cells}
    out['r180'] = {(N-1-r, N-1-c) for r,c in cells}
    out['fh']   = {(r, N-1-c) for r,c in cells}
    out['fv']   = {(N-1-r, c) for r,c in cells}
    out['tp']   = {(c, r) for r,c in cells}
    out['atp']  = {(N-1-c, N-1-r) for r,c in cells}
    return out

